import sys
import re
import xml.etree.ElementTree as ET

def evaluate_expression(expr, variables):
    try:
        # Replace variables with their values and evaluate the expression
        for var, val in variables.items():
            expr = expr.replace(var, str(val))
        return eval(expr)
    except:
        return 0.0  # Default to 0.0 if evaluation fails

def parse_xml(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    fields = []
    for field in root.findall('field'):
        name = field.get('name')
        expr = field.text
        fields.append((name, expr))
    return fields

def main():
    if len(sys.argv) != 2:
        print("Usage: python renderer.py <xml_file>")
        return

    xml_path = sys.argv[1]
    fields = parse_xml(xml_path)

    variables = {}
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        name, value = line.split('=', 1)
        try:
            variables[name] = float(value)
        except ValueError:
            continue

    for name, expr in fields:
        result = evaluate_expression(expr, variables)
        print(f"{name}={result}")

if __name__ == "__main__":
    main()
